import '../models/anniversary.dart';
import 'i18n.dart';

/// Locale-aware labels generated by calendar and Markdown exports.
///
/// Create one instance per export call so its labels follow the active locale
/// without changing authored content or cached export state.
class ExportUiCopy {
  const ExportUiCopy(this.locale);

  factory ExportUiCopy.current() => ExportUiCopy(I18n.current);

  final AppLocale locale;

  bool get _isEn => locale == AppLocale.en;

  String get eventsCalendarName => _isEn ? 'Duoyi · Calendar' : '多仪 · 日程';

  String get anniversariesCalendarName =>
      _isEn ? 'Duoyi · Anniversaries' : '多仪 · 纪念日';

  String get anniversaryRangeHint =>
      _isEn ? 'Preserve dates and recurrence rules' : '保留日期和重复规则';

  String get chooseRange => _isEn
      ? 'Choose at least one range to generate an export.'
      : '请至少选择一个范围后生成导出。';
  String get accountChanging => _isEn
      ? 'Export will be available when the account is ready.'
      : '账号准备就绪后即可导出。';
  String get snapshotHint => _isEn
      ? 'Preview is a snapshot. Changing the range or source data clears it; generate again to refresh.'
      : '预览是生成时的快照。范围或源数据变更后，请重新生成。';
  String get calDavScope => _isEn
      ? 'CalDAV sync uses the entire calendar, independently of the export range.'
      : 'CalDAV 同步完整日历，不受导出范围影响。';
  String get copyFailed =>
      _isEn ? 'Could not copy. Please try again.' : '复制失败，请重试。';
  String get pushFailed => _isEn
      ? 'CalDAV sync did not finish. Some events may already have synced; check the remote calendar before retrying.'
      : 'CalDAV 同步未完成，部分事件可能已同步，请先检查远端日历再重试。';

  String get configurationFailed => _isEn
      ? 'Could not save the calendar configuration. Please try again.'
      : '日历配置保存失败，请重试。';

  String get todosHeading => _isEn ? 'Todo List' : '待办清单';
  String get ungroupedTodo => _isEn ? 'Ungrouped' : '未分组';
  String get attachment => _isEn ? 'Attachment' : '附件';
  String get attachments => _isEn ? 'Attachments' : '附件';
  String get notesHeading => _isEn ? 'Notes' : '笔记';
  String get pinned => _isEn ? 'Pinned' : '置顶';
  String get archived => _isEn ? 'Archived' : '归档';
  String get diaryHeading => _isEn ? 'Diary' : '日记';
  String get tagsLabel => _isEn ? 'Tags:' : '标签:';
  String get anniversariesHeading => _isEn ? 'Anniversaries' : '纪念日';
  String get nextOccurrenceLabel => _isEn ? 'Next:' : '下一次:';
  String get goalsHeading => _isEn ? 'Goals' : '目标';

  String anniversaryType(AnniversaryType type) => switch (type) {
    AnniversaryType.birthday => _isEn ? 'Birthday' : '生日',
    AnniversaryType.memorial => _isEn ? 'Anniversary' : '纪念日',
    AnniversaryType.normal => _isEn ? 'Countdown' : '倒数',
    AnniversaryType.custom => _isEn ? 'Custom' : '自定义',
  };

  String anniversaryCalendar(AnniversaryCalendarType type) => switch (type) {
    AnniversaryCalendarType.solar => _isEn ? 'Solar' : '公历',
    AnniversaryCalendarType.lunar => _isEn ? 'Lunar' : '农历',
  };
}
